import {parseMarketingCSV,marketingDemo,marketingCSV,analyzeMarketing} from './marketing-core.mjs';
import {latestDataset,saveDataset,datasetHistory} from './datasets-client.mjs';
const state={rows:marketingDemo(),source:'demo',name:'Учебные кампании',version:0,loaded:false,loading:null,error:'',targetCPA:3000,filter:'all',pending:false,generation:0};
const esc=v=>String(v).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const num=v=>v===null?'—':new Intl.NumberFormat('ru-RU',{maximumFractionDigits:2}).format(v);
const money=v=>v===null?'—':num(v)+' ₸';
const names={instagram:'Instagram',facebook:'Facebook',google:'Google Ads',tiktok:'TikTok',other:'Другая'};
function download(name,content){const u=URL.createObjectURL(new Blob(['\uFEFF',content],{type:'text/csv;charset=utf-8'}));const a=document.createElement('a');a.href=u;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(u),1000);}
async function ensure(){if(state.loaded)return;if(!state.loading){const g=state.generation;state.loading=latestDataset('marketing').then(d=>{state.version=d.version;if(g===state.generation&&d.dataset)Object.assign(state,{rows:d.dataset.rows,source:d.dataset.source,name:d.dataset.name});state.loaded=true;state.error='';}).finally(()=>{state.loading=null;});}await state.loading;}
export function marketingPage(){return '<div class="page-head"><div><h1>Маркетинг и реклама</h1><p class="subtitle">Какие кампании приводят покупки — и что стоит проверить.</p></div></div><div id="marketing-workspace"></div>';}
export function mountMarketing(app,notify){
  const host=app.querySelector('#marketing-workspace');
  function draw(){if(!host.isConnected)return;if(!state.loaded&&!state.error){host.innerHTML='<section class="panel" role="status">Загружаем сохранённые рекламные отчёты…</section>';return;}
    const report=analyzeMarketing(state.rows,{targetCPA:state.targetCPA,minPurchases:10,lagDays:2});
    const campaigns=report.campaigns.filter(c=>state.filter==='all'||c.platform===state.filter);
    host.innerHTML=`<div class="marketing-banner"><strong>${state.source==='demo'?'Демонстрация · вымышленные кампании':'Сохранённый отчёт · '+esc(state.name)}</strong><span>${esc(report.start)} — ${esc(report.end)} · ₸ KZT</span></div>${state.error?`<div class="error-box" role="alert">${esc(state.error)}</div>`:''}<div class="stats marketing-stats"><div class="stat"><div class="stat-label">Расходы</div><div class="stat-value">${money(report.summary.spend)}</div></div><div class="stat"><div class="stat-label">Клики</div><div class="stat-value">${num(report.summary.clicks)}</div></div><div class="stat"><div class="stat-label">Кампаний</div><div class="stat-value">${report.campaigns.length}</div></div></div><section class="panel"><div class="panel-head"><h2>Рекомендации по кампаниям</h2><span class="badge neutral">Решение принимает владелец</span></div><form id="marketing-settings" class="budget-form"><label>Целевая стоимость покупки, ₸<input id="target-cpa" type="number" min="0.01" step="0.01" max="1000000000" required value="${state.targetCPA}"></label><button class="button" type="submit">Пересчитать рекомендации</button><label>Платформа<select id="marketing-platform"><option value="all">Все платформы</option>${Object.entries(names).map(([k,v])=>`<option value="${k}" ${state.filter===k?'selected':''}>${v}</option>`).join('')}</select></label></form><p class="meta">Рекомендации основаны на расходах и покупках. Первое решение — после 7 полных дней и минимум 10 покупок; последние 2 дня исключены из рекомендаций из-за задержки конверсий.</p><div class="campaign-list">${campaigns.map(c=>`<article class="campaign-card"><div class="panel-head"><div><span class="eyebrow">${names[c.platform]} · ${esc(c.attribution)}</span><h3>${esc(c.campaign)}</h3><span class="meta">Аккаунт ${esc(c.account_id)} · ${esc(c.campaign_id)}</span></div><span class="badge ${c.recommendation.action==='review-reduce'?'warn':'neutral'}">${esc(c.recommendation.label)}</span></div><div class="campaign-metrics"><div><span>Расходы</span><strong>${money(c.metrics.spend)}</strong></div><div><span>Покупки по атрибуции</span><strong>${num(c.metrics.purchases)}</strong></div><div><span>CPA · стоимость покупки</span><strong>${money(c.metrics.cpa)}</strong></div><div><span>ROAS · выручка / расход</span><strong>${num(c.metrics.roas)}${c.metrics.roas===null?'':'×'}</strong></div></div><p class="note">${esc(c.recommendation.reason)}</p><details><summary>Данные и основание рекомендации</summary><p class="meta">Зрелых дней: ${c.mature.days}. Для рекомендации: CPA ${money(c.mature.metrics.cpa)}, покупок ${num(c.mature.metrics.purchases)}. Клики: ${num(c.metrics.clicks)}, CTR: ${num(c.metrics.ctr)}%, заявки: ${num(c.metrics.leads)}, выручка по атрибуции: ${money(c.metrics.revenue)}.</p></details></article>`).join('')||'<p>Для выбранной платформы нет кампаний.</p>'}</div></section><section class="panel"><h2>Сравнение источников</h2><p class="note">Покупки в рекламных кабинетах — не уникальные клиенты. Несколько платформ могут приписать себе одну покупку. Для сравнения нужны одинаковые события, даты, часовой пояс и окно атрибуции. ROAS не учитывает себестоимость и не равен прибыли.</p><div class="table-wrap"><table><thead><tr><th>Источник / атрибуция</th><th>Расходы</th><th>Покупки</th><th>CPA</th><th>ROAS</th></tr></thead><tbody>${report.platforms.map(p=>`<tr><td>${names[p.platform]}<small> · ${esc(p.attribution)}</small></td><td>${money(p.metrics.spend)}</td><td>${num(p.metrics.purchases)}</td><td>${money(p.metrics.cpa)}</td><td>${num(p.metrics.roas)}</td></tr>`).join('')}</tbody></table></div>${report.warnings.map(w=>`<p class="meta">${esc(w)}</p>`).join('')}</section><section class="panel"><div class="panel-head"><h2>Данные рекламных кабинетов</h2><span class="badge neutral">Прямые API не подключены</span></div><p class="note">Meta/Instagram, Google Ads и TikTok требуют авторизации владельца. Сейчас работает импорт отчёта в общий формат.</p><details><summary>Загрузить отчёт и сохранить историю</summary><p class="note">Одна строка — кампания за день. Только KZT, одинаковый часовой пояс. В purchases указывайте именно покупки, а не все конверсии. Заполните дни без активности нулями. Новый файл должен содержать полную обновлённую историю; он заменит текущий снимок, сохранив предыдущий.</p><button class="button" id="marketing-template">Скачать пример CSV</button><label class="form-control">CSV отчёта<input id="marketing-file" type="file" accept=".csv,text/csv" ${state.pending?'disabled':''}></label><details><summary>Или вставить CSV</summary><textarea id="marketing-csv" rows="6" aria-label="Маркетинговый CSV"></textarea><button class="button primary" id="marketing-import" ${state.pending?'disabled':''}>Проверить и сохранить</button></details><p class="meta">До 1 МБ / 5 000 строк. Отчёт сохраняется на сервере в вашем пространстве. Ключи доступа и персональные данные клиентов не нужны.</p></details></section>`;
    host.querySelector('#marketing-settings').onsubmit=e=>{e.preventDefault();const v=Number(host.querySelector('#target-cpa').value);if(!Number.isFinite(v)||v<=0||v>1e9){notify('Укажите положительную целевую стоимость покупки.');return;}state.targetCPA=v;draw();};
    host.querySelector('#marketing-platform').onchange=e=>{state.filter=e.target.value;draw();};
    host.querySelector('#marketing-template').onclick=()=>download('qadam-marketing-example.csv',marketingCSV(marketingDemo()));
    host.querySelector('#marketing-file').onchange=async e=>{const f=e.target.files[0];if(!f)return;if(f.size>1024*1024){notify('Файл больше 1 МБ.');return;}await apply(await f.text(),f.name);};
    host.querySelector('#marketing-import').onclick=()=>void apply(host.querySelector('#marketing-csv').value,'Маркетинговый CSV');
    datasetHistory(host,'marketing',async d=>{await ensure();const r=await saveDataset('marketing',d.rows,d.name,d.source,state.version);state.generation++;state.rows=r.dataset.rows;state.source=r.dataset.source;state.name=r.dataset.name;state.version=r.version;draw();},notify);
  }
  async function apply(text,name){if(state.pending)return;state.pending=true;host.querySelectorAll('#marketing-file,#marketing-import').forEach(el=>el.disabled=true);try{const parsed=parseMarketingCSV(text);if(parsed.errors.length)throw Error(parsed.errors.slice(0,5).map(e=>(e.line?'Строка '+e.line+': ':'')+e.message).join('\n'));await ensure();const r=await saveDataset('marketing',parsed.rows,name,'upload',state.version);state.generation++;state.rows=r.dataset.rows;state.source='upload';state.name=name;state.version=r.version;state.error='';notify(r.duplicate?'Этот отчёт уже сохранён.':'Отчёт сохранён. Рекомендации обновлены.');}catch(e){state.error=e.message;if(e.status===409)state.loaded=false;notify(e.message);}finally{state.pending=false;draw();}}
  draw();void ensure().then(draw).catch(e=>{state.error=e.message;draw();});
}
